// Jenkinsfile - 企业级 Java CI/CD 流水线
pipeline {
    agent {
        kubernetes {
            label 'maven-app'
            yaml """
apiVersion: v1
kind: Pod
spec:
  containers:
  - name: maven
    image: maven:3.9-eclipse-temurin-21
    command:
    - cat
    tty: true
    volumeMounts:
    - name: maven-settings
      mountPath: /root/.m2/settings.xml
      subPath: settings.xml
    - name: maven-repo
      mountPath: /root/.m2/repository
  - name: docker
    image: docker:24-dind
    command:
    - cat
    tty: true
    privileged: true
    volumeMounts:
    - name: docker-sock
      mountPath: /var/run/docker.sock
  volumes:
  - name: maven-settings
    configMap:
      name: maven-settings
  - name: maven-repo
    persistentVolumeClaim:
      claimName: maven-repo-pvc
  - name: docker-sock
    hostPath:
      path: /var/run/docker.sock
"""
        }
    }

    environment {
        APP_NAME = 'my-application'
        VERSION = sh(script: 'mvn help:evaluate -Dexpression=project.version -q -DforceStdout', returnStdout: true).trim()
        BUILD_TAG = "${VERSION}-${env.BUILD_NUMBER}"
        GIT_COMMIT_SHORT = sh(script: 'git rev-parse --short HEAD', returnStdout: true).trim()
        DOCKER_REGISTRY = 'registry.example.com'
    }

    options {
        buildDiscarder(logRotator(numToKeepStr: '20', artifactNumToKeepStr: '5'))
        disableConcurrentBuilds()
        timeout(time: 60, unit: 'MINUTES')
        timestamps()
        ansiColor('xterm')
    }

    stages {
        stage('Checkout') {
            steps {
                git branch: 'main',
                    url: 'https://github.com/company/my-application.git',
                    credentialsId: 'github-credentials'
            }
        }

        stage('Build') {
            steps {
                container('maven') {
                    sh 'mvn clean compile -B'
                }
            }
        }

        stage('Test') {
            parallel {
                stage('Unit Tests') {
                    steps {
                        container('maven') {
                            sh 'mvn test -B'
                        }
                    }
                    post {
                        always {
                            junit '**/target/surefire-reports/*.xml'
                            publishCoverage adapters: [jacocoAdapter('target/site/jacoco/jacoco.xml')]
                        }
                    }
                }

                stage('Integration Tests') {
                    steps {
                        container('maven') {
                            sh 'mvn verify -DskipUnitTests -B'
                        }
                    }
                    post {
                        always {
                            junit '**/target/failsafe-reports/*.xml'
                        }
                    }
                }
            }
        }

        stage('Code Quality') {
            steps {
                container('maven') {
                    withSonarQubeEnv('SonarQube') {
                        sh 'mvn sonar:sonar -B'
                    }
                }
            }
        }

        stage('Security Scan') {
            parallel {
                stage('Dependency Check') {
                    steps {
                        container('maven') {
                            sh 'mvn dependency-check:check -B'
                        }
                    }
                    post {
                        always {
                            publishHTML([
                                allowMissing: false,
                                alwaysLinkToLastBuild: true,
                                keepAll: true,
                                reportDir: 'target',
                                reportFiles: 'dependency-check-report.html',
                                reportName: 'Dependency Check Report'
                            ])
                        }
                    }
                }

                stage('Container Scan') {
                    steps {
                        container('docker') {
                            sh '''
                                trivy image --severity HIGH,CRITICAL \
                                    --exit-code 1 \
                                    ${DOCKER_REGISTRY}/${APP_NAME}:${BUILD_TAG}
                            '''
                        }
                    }
                }
            }
        }

        stage('Quality Gate') {
            steps {
                timeout(time: 5, unit: 'MINUTES') {
                    script {
                        def qg = waitForQualityGate()
                        if (qg.status != 'OK') {
                            error "Quality Gate failed: ${qg.status}"
                        }
                    }
                }
            }
        }

        stage('Build Image') {
            steps {
                container('docker') {
                    script {
                        docker.withRegistry("https://${DOCKER_REGISTRY}", 'registry-credentials') {
                            def appImage = docker.build(
                                "${DOCKER_REGISTRY}/${APP_NAME}:${BUILD_TAG}",
                                "--build-arg VERSION=${VERSION} ."
                            )
                            appImage.push()
                            appImage.push('latest')
                        }
                    }
                }
            }
        }

        stage('Deploy to Staging') {
            when {
                branch 'main'
            }
            steps {
                container('maven') {
                    sh """
                        helm upgrade --install ${APP_NAME} ./helm \
                            --set image.tag=${BUILD_TAG} \
                            --set environment=staging \
                            --namespace staging \
                            --timeout 5m \
                            --atomic
                    """
                }
            }
        }

        stage('Deploy to Production') {
            when {
                branch 'main'
            }
            steps {
                timeout(time: 30, unit: 'MINUTES') {
                    input message: 'Deploy to production?', ok: 'Deploy', submitter: 'release-managers'
                }
                container('maven') {
                    sh """
                        helm upgrade --install ${APP_NAME} ./helm \
                            --set image.tag=${BUILD_TAG} \
                            --set environment=production \
                            --namespace production \
                            --timeout 10m \
                            --atomic
                    """
                }
            }
        }
    }

    post {
        always {
            cleanWs()
        }
        success {
            slackSend channel: '#jenkins',
                     color: 'good',
                     message: "✅ ${env.JOB_NAME} #${env.BUILD_NUMBER} succeeded"
        }
        failure {
            slackSend channel: '#jenkins',
                     color: 'danger',
                     message: "❌ ${env.JOB_NAME} #${env.BUILD_NUMBER} failed"
        }
    }
}

// vars/buildMavenApp.groovy
def call(Map config = [:]) {
    def defaultConfig = [
        javaVersion: '21',
        mavenGoals: 'clean verify',
        skipTests: false,
        enableCoverage: true,
        enableSecurityScan: true,
        enableSonar: true
    ]
    config = defaultConfig + config

    pipeline {
        agent {
            kubernetes {
                label "maven-${env.BUILD_NUMBER}"
                yaml """
apiVersion: v1
kind: Pod
spec:
  containers:
  - name: maven
    image: maven:3.9-eclipse-temurin-${config.javaVersion}
    command: [cat]
    tty: true
"""
            }
        }

        stages {
            stage('Build') {
                steps {
                    container('maven') {
                        sh "mvn ${config.mavenGoals} ${config.skipTests ? '-DskipTests' : ''} -B"
                    }
                }
            }

            stage('Test') {
                when {
                    expression { !config.skipTests }
                }
                steps {
                    container('maven') {
                        sh 'mvn test -B'
                    }
                }
                post {
                    always {
                        junit '**/target/surefire-reports/*.xml'
                    }
                }
            }

            stage('Quality & Security') {
                parallel {
                    stage('SonarQube') {
                        when {
                            expression { config.enableSonar }
                        }
                        steps {
                            container('maven') {
                                withSonarQubeEnv('SonarQube') {
                                    sh 'mvn sonar:sonar -B'
                                }
                            }
                        }
                    }

                    stage('Security Scan') {
                        when {
                            expression { config.enableSecurityScan }
                        }
                        steps {
                            container('maven') {
                                sh 'mvn dependency-check:check -B'
                            }
                        }
                    }
                }
            }
        }
    }
}

pipeline {
    agent any
    stages {
        stage('Compliance Checks') {
            parallel {
                stage('SonarQube Analysis') {
                    steps {
                        withSonarQubeEnv('SonarQube') {
                            sh 'mvn sonar:sonar -B'
                        }
                    }
                }

                stage('License Compliance') {
                    steps {
                        sh '''
                            mvn license:check -B
                            mvn cyclonedx:makeAggregateBom -B
                        '''
                    }
                }
            }
        }

        stage('Compliance Gate') {
            steps {
                script {
                    def qg = waitForQualityGate()
                    if (qg.status != 'OK') {
                        error "Compliance gate failed: ${qg.status}"
                    }

                    def highVulns = sh(
                        script: "grep -c '\"severity\":\"HIGH\"' target/dependency-check-report.json || echo 0",
                        returnStdout: true
                    ).trim() as Integer

                    if (highVulns > 0) {
                        error "Found ${highVulns} high severity vulnerabilities"
                    }
                }
            }
        }
    }
}

// Pipeline 中使用缓存
pipeline {
    agent {
        kubernetes {
            yaml """
apiVersion: v1
kind: Pod
spec:
  containers:
  - name: maven
    image: maven:3.9-eclipse-temurin-21
    command: [cat]
    tty: true
    volumeMounts:
    - name: maven-repo
      mountPath: /root/.m2/repository
  volumes:
  - name: maven-repo
    persistentVolumeClaim:
      claimName: maven-repo-cache
"""
        }
    }
    stages {
        stage('Build with Cache') {
            steps {
                container('maven') {
                    sh 'mvn clean install -Dmaven.repo.local=/root/.m2/repository -B'
                }
            }
        }
    }
}

// 并行构建优化示例
pipeline {
    agent any
    stages {
        stage('Parallel Build Matrix') {
            matrix {
                axes {
                    axis {
                        name 'JAVA_VERSION'
                        values '11', '17', '21'
                    }
                    axis {
                        name 'OS'
                        values 'linux', 'windows'
                    }
                }
                agent {
                    kubernetes {
                        yaml """
apiVersion: v1
kind: Pod
spec:
  containers:
  - name: jdk
    image: eclipse-temurin:${JAVA_VERSION}-jdk
    command: [cat]
    tty: true
"""
                    }
                }
                stages {
                    stage('Build') {
                        steps {
                            container('jdk') {
                                sh './mvnw clean verify -B'
                            }
                        }
                    }
                }
            }
        }
    }
}

